<?php
require_once __DIR__.'/../includes/functions.php';require_role('mentor','admin');require_once __DIR__.'/../config/database.php';$st=$pdo->query("SELECT e.*,u.full_name,u.email,s.skill_name,p.title project_title FROM evidence_submissions e JOIN users u ON u.user_id=e.user_id JOIN skills s ON s.skill_id=e.skill_id LEFT JOIN projects p ON p.project_id=e.project_id WHERE e.status IN ('pending','under_review','changes_requested') ORDER BY e.submitted_at ASC");$queue=$st->fetchAll();$pageTitle='Evidence review';$active='mentor';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Mentor workspace</span><h1 class="h1">Evidence review</h1><p>Review the student's submitted work and provide clear, actionable feedback.</p></div><span class="pill pill-amber"><?=count($queue)?> awaiting attention</span></div><div class="grid grid-2"><?php foreach($queue as $item):?><article class="card review-card"><div class="row-between"><span class="pill pill-amber"><?=h(ucwords(str_replace('_',' ',$item['status'])))?></span><span class="muted tiny"><?=date('d M Y',strtotime($item['submitted_at']))?></span></div><h3 style="margin-top:13px"><?=h($item['title'])?></h3><p style="margin:3px 0 0"><?=h($item['full_name'])?> · <?=h($item['email'])?></p><div class="tag-row"><span class="tag"><?=h($item['skill_name'])?></span><?php if($item['project_title']):?><span class="tag"><?=h($item['project_title'])?></span><?php endif;?></div><?php if($item['description']):?><blockquote><?=nl2br(h($item['description']))?></blockquote><?php endif;?><?php if($item['evidence_url']):?><a class="link-arrow" target="_blank" rel="noopener noreferrer" href="<?=h($item['evidence_url'])?>">Open submitted evidence ↗</a><?php endif;?><form method="post" action="<?=h(url('mentor/review.php'))?>" style="margin-top:17px"><?=csrf_field()?><input type="hidden" name="evidence_id" value="<?=(int)$item['evidence_id']?>"><div class="field"><label>Review decision</label><select class="select" name="decision"><option value="verified">Verify evidence</option><option value="changes_requested">Request changes</option><option value="rejected">Reject evidence</option></select></div><div class="field"><label>Verified proficiency level (only used when verified)</label><select class="select" name="verified_level"><option value="1">1 · Beginner</option><option value="2">2 · Basic</option><option value="3" selected>3 · Intermediate</option><option value="4">4 · Advanced</option><option value="5">5 · Expert</option></select></div><div class="field"><label>Feedback for student</label><textarea class="textarea" name="reviewer_feedback" rows="3" placeholder="Explain what was demonstrated and what could be improved."></textarea></div><button class="btn btn-primary btn-block">Save review</button></form></article><?php endforeach;?></div><?php if(!$queue):?><div class="card empty-state"><div class="empty-icon">✓</div><h2>Review queue is clear</h2><p>New student evidence submissions will appear here.</p></div><?php endif;?></div></main><?php include __DIR__.'/../includes/footer.php';?>
